'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const molecules={H2:['H','H'],O2:['O','O'],N2:['N','N'],Cl2:['Cl','Cl'],H2O:['H','H','O'],NH3:['N','H','H','H'],HCl:['H','Cl']};
const formulas={H2:'H₂',O2:'O₂',N2:'N₂',Cl2:'Cl₂',H2O:'H₂O',NH3:'NH₃',HCl:'HCl'};
const recipes=[{a:'H2',b:'O2',product:'H2O'},{a:'N2',b:'H2',product:'NH3'},{a:'H2',b:'Cl2',product:'HCl'}];
const orders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
let variant=OrionProgress.variant('atoms'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,amounts=[0,0],solved=false,hintDepth=0,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return{...recipes[orders[v][s]],target:2+2*((v+s)%2)};}
function totals(q=challenge(),a=amounts){const before={},after={};for(const [i,k] of [q.a,q.b].entries())for(const atom of molecules[k])before[atom]=(before[atom]||0)+a[i];for(const atom of molecules[q.product])after[atom]=(after[atom]||0)+q.target;return{before,after};}
function balanced(q=challenge(),a=amounts){const x=totals(q,a);return Object.keys(x.after).every(k=>(x.before[k]||0)===x.after[k]);}
function setAmount(i,n){if(solved||![0,1].includes(i)||!Number.isInteger(n)||n<0||n>6)return;amounts[i]=n;state='ready';render();}
function resetTrial(){amounts=[0,0];solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('atoms')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(!balanced())state='unequal';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('matter');}render();if(solved&&stage<2)$('next').focus();}
function tile(k){return `<span class="molecule" aria-label="${formulas[k]}">${molecules[k].map(a=>`<span class="atom ${a}" aria-hidden="true">${a}</span>`).join('')}</span>`;}
function hints(){const q=challenge(),x=totals();return[t('Count each letter separately. A molecule tile carries all the atoms shown inside it.','每種字母分開數。一個分子圖塊包含裏面顯示的所有原子。'),t(`The target has ${Object.entries(x.after).map(([k,n])=>`${n} ${k}`).join(', ')} atoms. Compare these with your supplies.`,`目標有 ${Object.entries(x.after).map(([k,n])=>`${n} 個 ${k}`).join('、')} 原子。與你提供的原子比較。`),t('Add or remove whole tiles until every row has equal counts. Do not change the atoms inside a tile.','增加或減少完整圖塊，直到每行數目相同。不要改變圖塊裏的原子。')];}
function render(){const q=challenge(),x=totals(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Atom Treasury · Orion','原子寶庫 · Orion');$('stageTitle').textContent=t(`Mosaic ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅拼畫 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Treasury seals · ${p} / 3`,`寶庫封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('controls').innerHTML=[q.a,q.b].map((k,i)=>`<section class="molecule-card"><h3>${t('Supply','提供')} ${formulas[k]}</h3><div class="adjust"><button data-i="${i}" data-d="-1" aria-label="${t('Remove one','減少一個')} ${formulas[k]}" ${solved||amounts[i]===0?'disabled':''}>−</button><strong>${amounts[i]}</strong><button data-i="${i}" data-d="1" aria-label="${t('Add one','增加一個')} ${formulas[k]}" ${solved||amounts[i]===6?'disabled':''}>+</button><span>${t('molecules','個分子')}</span></div><div class="tiles">${Array.from({length:amounts[i]},()=>tile(k)).join('')||`<span>${t('Empty tray','空盤')}</span>`}</div><small>${t('One tile:','每個圖塊：')} ${tile(k)}</small></section>`).join('');
$('goal').textContent=t(`Target: ${q.target} ${formulas[q.product]} molecules. Supply exactly the same atoms.`,`目標：${q.target} 個 ${formulas[q.product]} 分子。提供剛好相同的原子。`);$('target').innerHTML=`<div class="tiles">${Array.from({length:q.target},()=>tile(q.product)).join('')}</div>`;$('counts').innerHTML=`<p>${t('Atom · your supply / target','原子 · 你提供的 / 目標')}</p>`+Object.keys(x.after).map(k=>`<div class="count-row ${(x.before[k]||0)===x.after[k]?'match':''}"><strong>${k}</strong><span>${x.before[k]||0} / ${x.after[k]} ${(x.before[k]||0)===x.after[k]?'✓':'≠'}</span></div>`).join('');
$('feedback').textContent=state==='success'?t('Every kind of atom matches. A treasury seal shines!','每種原子都吻合，寶庫封印亮起了！'):state==='unequal'?t('Some atom counts differ. Compare each row and adjust your tiles.','有原子數目不同。比較每一行，再調整圖塊。'):t('Watch the counts change as you add or remove tiles.','增加或減少圖塊，觀察原子數目怎樣改變。');$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('matter')?t('Matter Sigil saved in your collection.','物質符印已存入收藏。'):'';}
$('controls').onclick=e=>{const b=e.target.closest('button[data-i]');if(!b)return;const i=Number(b.dataset.i),d=Number(b.dataset.d);setAmount(i,amounts[i]+d);$('controls').querySelector(`[data-i="${i}"][data-d="${d}"]`)?.focus();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('atoms',variant);observedVariant=OrionProgress.variant('atoms');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('matter');render();};function syncProgress(){const v=OrionProgress.variant('atoms'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('matter')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
